import json
with open('artifacts/ppi_empirical_validation.json') as f:
    data = json.load(f)

# Check if there's a summary section
top_keys = list(data.keys())
print('Top-level keys:', top_keys)

# Compute per-topology averages across 8 configs
from collections import defaultdict
topo_method_reductions = defaultdict(lambda: defaultdict(list))

for cfg_name, cfg_data in data['per_config'].items():
    for topo, topo_data in cfg_data.items():
        for method, method_data in topo_data['methods'].items():
            br = method_data.get('bias_reduction')
            if br is not None:
                topo_method_reductions[topo][method].append(br)

print('\n=== Per-topology mean bias reduction (MAE-based) ===')
for topo in data['meta']['topologies']:
    print(f'\n{topo}:')
    for method in ['ppi', 'mcsimex', 'dsl', 'naive_plugin', 'mla']:
        vals = topo_method_reductions[topo][method]
        if vals:
            mean_val = sum(vals) / len(vals)
            print(f'  {method}: {mean_val*100:.1f}% (n={len(vals)})')
        else:
            print(f'  {method}: N/A')

# Grand means for PPI and MC-SIMEX
print('\n=== Grand means ===')
for method in ['ppi', 'mcsimex']:
    all_vals = []
    for topo in data['meta']['topologies']:
        vals = topo_method_reductions[topo][method]
        if vals:
            all_vals.extend(vals)
    if all_vals:
        print(f'{method}: {sum(all_vals)/len(all_vals)*100:.1f}% (n={len(all_vals)})')
"

